package com.opensocket.aievent.core.iam.token.domain;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;class TokenScopeTest{@Test void enforcesPermissionSubsetAndNetwork(){TokenScope s=new TokenScope(Set.of("identity.user.read"),Set.of("api"),Set.of("/api/identity"),Set.of("10.0.0.0/8"));assertTrue(s.permitsIp("10.1.2.3"));assertFalse(s.permitsIp("192.168.1.1"));assertThrows(TokenDomainException.class,()->s.requireSubsetOf(Set.of("identity.group.read")));}}
